    @SerialName("connectionLimit") ConnectionLimit,
    @SerialName("databaseConnectionFailed") DatabaseConnectionFailed,
    @SerialName("databaseConstraintFailed") DatabaseConstraintFailed,
    @SerialName("databaseDuplicate") DatabaseDuplicate,
    @SerialName("databaseError") DatabaseError,
    @SerialName("databaseLockTimeout") DatabaseLockTimeout,
    @SerialName("databasePoolTimeout") DatabasePoolTimeout,
    @SerialName("databaseQueryCancelled") DatabaseQueryCancelled,
    @SerialName("databaseQueryTimeout") DatabaseQueryTimeout,
    @SerialName("databaseReferenceConflict") DatabaseReferenceConflict,
    @SerialName("databaseResultInvalid") DatabaseResultInvalid,
    @SerialName("databaseTransactionConflict") DatabaseTransactionConflict,
    @SerialName("databaseUnavailable") DatabaseUnavailable,
    @SerialName("discordAnnouncementTimeout") DiscordAnnouncementTimeout,
    @SerialName("discordChannelInvalid") DiscordChannelInvalid,
    @SerialName("discordConfiguration") DiscordConfiguration,
    @SerialName("discordRoleMissing") DiscordRoleMissing,
    @SerialName("internalOperationFailed") InternalOperationFailed,
    @SerialName("liveStateUnavailable") LiveStateUnavailable,
    @SerialName("lobbyLoadTimeout") LobbyLoadTimeout,
    @SerialName("lobbyQueueFull") LobbyQueueFull,
    @SerialName("noAccount") NoAccount,
    @SerialName("operationTimeout") OperationTimeout,
    @SerialName("outdatedClient") OutdatedClient,
    @SerialName("passwordProcessingBusy") PasswordProcessingBusy,
    @SerialName("passwordProcessingFailed") PasswordProcessingFailed,
    @SerialName("passwordRateLimited") PasswordRateLimited,
    @SerialName("passwordResetRequired") PasswordResetRequired,
    @SerialName("persistenceUncertain") PersistenceUncertain,
    @SerialName("recordNotFound") RecordNotFound,
    @SerialName("savedGameInconsistentPlayers") SavedGameInconsistentPlayers,
    @SerialName("savedGameInvalidAction") SavedGameInvalidAction,
    @SerialName("savedGameInvalidSeed") SavedGameInvalidSeed,
    @SerialName("savedGameInvalidCharacter") SavedGameInvalidCharacter,
    @SerialName("savedGameUnknownVariant") SavedGameUnknownVariant,
    @SerialName("serverDataInvalid") ServerDataInvalid,
    @SerialName("serverDraining") ServerDraining,
    @SerialName("serverIoError") ServerIoError,
    @SerialName("serverUnavailable") ServerUnavailable,
    @SerialName("sessionGenerationExhausted") SessionGenerationExhausted,
    @SerialName("sessionReplaced") SessionReplaced,
    @SerialName("tableFailed") TableFailed,
    @SerialName("tableUnreadable") TableUnreadable,
    @SerialName("upstreamConnectionFailed") UpstreamConnectionFailed,
    @SerialName("upstreamHttpError") UpstreamHttpError,
    @SerialName("upstreamRequestInvalid") UpstreamRequestInvalid,
    @SerialName("upstreamResponseInvalid") UpstreamResponseInvalid,
    @SerialName("upstreamTimeout") UpstreamTimeout,
    @SerialName("upstreamUnauthorized") UpstreamUnauthorized,
    @SerialName("workerFailed") WorkerFailed,
}

