/** A message of the server. */
sealed interface Inbound

/** A message of the server with a name this version of the protocol does not have. */
class InUnknown(val command: String, val data: JsonElement?) : Inbound

/** A message of the server that does not read as what its name promises: the protocol has changed. */
class InInvalid(val command: String, val data: JsonElement?, val error: String) : Inbound

