/** Reads a frame's command and data (the part after the first space; null if there is none). */
fun decodeInbound(command: String, data: JsonElement?): Inbound {
    val body = data ?: kotlinx.serialization.json.JsonObject(emptyMap())
    return try {
        when (command) {
            "blocked" -> InBlocked(ProtocolJson.decodeFromJsonElement<Blocked>(body))
            "chat" -> InChat(ProtocolJson.decodeFromJsonElement<Chat>(body))
            "chatDeleted" -> InChatDeleted(ProtocolJson.decodeFromJsonElement<ChatDeleted>(body))
            "chatList" -> InChatList(ProtocolJson.decodeFromJsonElement<ChatList>(body))
            "chatTyping" -> InChatTyping(ProtocolJson.decodeFromJsonElement<ChatTyping>(body))
            "clock" -> InClock(ProtocolJson.decodeFromJsonElement<Clock>(body))
            "connections" -> InConnections(ProtocolJson.decodeFromJsonElement<Connections>(body))
            "error" -> InError(ProtocolJson.decodeFromJsonElement<Notice>(body))
            "friends" -> InFriends(ProtocolJson.decodeFromJsonElement<Friends>(body))
            "gameEvent" -> InGameEvent(ProtocolJson.decodeFromJsonElement<GameEventMessage>(body))
            "gameFinished" -> InGameFinished(ProtocolJson.decodeFromJsonElement<GameFinished>(body))
            "gameHistoryAdded" -> InGameHistoryAdded(ProtocolJson.decodeFromJsonElement<GameSummary>(body))
            "gameState" -> InGameState(ProtocolJson.decodeFromJsonElement<GameState>(body))
            "idleReset" -> InIdleReset(ProtocolJson.decodeFromJsonElement<TableRef>(body))
            "idleWarning" -> InIdleWarning(ProtocolJson.decodeFromJsonElement<IdleWarning>(body))
            "lobbyStatus" -> InLobbyStatus(ProtocolJson.decodeFromJsonElement<LobbyStatus>(body))
            "note" -> InNote(ProtocolJson.decodeFromJsonElement<Note>(body))
            "pause" -> InPause(ProtocolJson.decodeFromJsonElement<Pause>(body))
            "pregame" -> InPregame(ProtocolJson.decodeFromJsonElement<Pregame>(body))
            "replayAction" -> InReplayAction(ProtocolJson.decodeFromJsonElement<ReplayAction>(body))
            "serverShutdown" -> InServerShutdown(ProtocolJson.decodeFromJsonElement<ServerShutdown>(body))
            "spectators" -> InSpectators(ProtocolJson.decodeFromJsonElement<Spectators>(body))
            "table" -> InTable(ProtocolJson.decodeFromJsonElement<Table>(body))
            "tableJoined" -> InTableJoined(ProtocolJson.decodeFromJsonElement<TableJoined>(body))
            "tableLeft" -> InTableLeft(ProtocolJson.decodeFromJsonElement<TableRef>(body))
            "tableList" -> InTableList(ProtocolJson.decodeFromJsonElement<TableList>(body))
            "tableOwner" -> InTableOwner(ProtocolJson.decodeFromJsonElement<TableOwner>(body))
            "tableRemoved" -> InTableRemoved(ProtocolJson.decodeFromJsonElement<TableRef>(body))
            "tableRestartDecliners" -> InTableRestartDecliners(ProtocolJson.decodeFromJsonElement<TableRestartDecliners>(body))
            "tableSettingsSuggestion" -> InTableSettingsSuggestion(ProtocolJson.decodeFromJsonElement<TableSettingsSuggestion>(body))
            "tableSuggestion" -> InTableSuggestion(ProtocolJson.decodeFromJsonElement<TableSuggestion>(body))
            "user" -> InUser(ProtocolJson.decodeFromJsonElement<User>(body))
            "userList" -> InUserList(ProtocolJson.decodeFromJsonElement<UserList>(body))
            "userRemoved" -> InUserRemoved(ProtocolJson.decodeFromJsonElement<UserRemoved>(body))
            "votes" -> InVotes(ProtocolJson.decodeFromJsonElement<Votes>(body))
            "warning" -> InWarning(ProtocolJson.decodeFromJsonElement<Notice>(body))
            "welcome" -> InWelcome(ProtocolJson.decodeFromJsonElement<Welcome>(body))
            else -> InUnknown(command, data)
        }
    } catch (e: Exception) {
        InInvalid(command, data, e.message ?: e.toString())
    }
}

