/** Reads a command of the client (the server never sends these; the tests do, to check the types). Throws if it is not one. */
fun decodeOutbound(command: String, data: JsonElement): Outbound = when (command) {
    "blockAdd" -> OutBlockAdd(ProtocolJson.decodeFromJsonElement<RelationshipRequest>(data))
    "blockRemove" -> OutBlockRemove(ProtocolJson.decodeFromJsonElement<RelationshipRequest>(data))
    "chat" -> OutChat(ProtocolJson.decodeFromJsonElement<ChatRequest>(data))
    "chatPm" -> OutChatPm(ProtocolJson.decodeFromJsonElement<ChatPmRequest>(data))
    "chatPmHistory" -> OutChatPmHistory(ProtocolJson.decodeFromJsonElement<ChatPmHistoryRequest>(data))
    "chatRead" -> OutChatRead(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "chatTyping" -> OutChatTyping(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "friendAdd" -> OutFriendAdd(ProtocolJson.decodeFromJsonElement<RelationshipRequest>(data))
    "friendRemove" -> OutFriendRemove(ProtocolJson.decodeFromJsonElement<RelationshipRequest>(data))
    "gameHistory" -> OutGameHistory(ProtocolJson.decodeFromJsonElement<PageRequest>(data))
    "gameInitLoad" -> OutGameInitLoad(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "gameLoaded" -> OutGameLoaded(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "gameStateLoad" -> OutGameStateLoad(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "idleReset" -> OutIdleReset(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "linkAdd" -> OutLinkAdd(ProtocolJson.decodeFromJsonElement<RelationshipRequest>(data))
    "linkList" -> OutLinkList(ProtocolJson.decodeFromJsonElement<Empty>(data))
    "linkRemove" -> OutLinkRemove(ProtocolJson.decodeFromJsonElement<RelationshipRequest>(data))
    "lobbyLoad" -> OutLobbyLoad(ProtocolJson.decodeFromJsonElement<Empty>(data))
    "note" -> OutNote(ProtocolJson.decodeFromJsonElement<NoteRequest>(data))
    "pause" -> OutPause(ProtocolJson.decodeFromJsonElement<PauseRequest>(data))
    "pauseQueue" -> OutPauseQueue(ProtocolJson.decodeFromJsonElement<PauseQueueRequest>(data))
    "playerAction" -> OutPlayerAction(ProtocolJson.decodeFromJsonElement<PlayerActionRequest>(data))
    "replayAction" -> OutReplayAction(ProtocolJson.decodeFromJsonElement<ReplayAction>(data))
    "replayCreate" -> OutReplayCreate(ProtocolJson.decodeFromJsonElement<ReplayCreateRequest>(data))
    "seedGames" -> OutSeedGames(ProtocolJson.decodeFromJsonElement<SeedGamesRequest>(data))
    "settings" -> OutSettings(ProtocolJson.decodeFromJsonElement<SettingsRequest>(data))
    "tableCreate" -> OutTableCreate(ProtocolJson.decodeFromJsonElement<TableCreateRequest>(data))
    "tableJoin" -> OutTableJoin(ProtocolJson.decodeFromJsonElement<TableJoinRequest>(data))
    "tableLeave" -> OutTableLeave(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "tableReattend" -> OutTableReattend(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "tableRestart" -> OutTableRestart(ProtocolJson.decodeFromJsonElement<TableRestartRequest>(data))
    "tableRestartDecline" -> OutTableRestartDecline(ProtocolJson.decodeFromJsonElement<TableRestartDeclineRequest>(data))
    "tableSetOwner" -> OutTableSetOwner(ProtocolJson.decodeFromJsonElement<TableSetOwnerRequest>(data))
    "tableSpectate" -> OutTableSpectate(ProtocolJson.decodeFromJsonElement<TableSpectateRequest>(data))
    "tableStart" -> OutTableStart(ProtocolJson.decodeFromJsonElement<TableStartRequest>(data))
    "tableSuggest" -> OutTableSuggest(ProtocolJson.decodeFromJsonElement<TableSuggestRequest>(data))
    "tableTerminate" -> OutTableTerminate(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "tableTerminateVote" -> OutTableTerminateVote(ProtocolJson.decodeFromJsonElement<TableTerminateVoteRequest>(data))
    "tableUnattend" -> OutTableUnattend(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "tableUpdate" -> OutTableUpdate(ProtocolJson.decodeFromJsonElement<TableUpdateRequest>(data))
    "tagAdd" -> OutTagAdd(ProtocolJson.decodeFromJsonElement<TagRequest>(data))
    "tagRemove" -> OutTagRemove(ProtocolJson.decodeFromJsonElement<TagRequest>(data))
    "tagRemoveAll" -> OutTagRemoveAll(ProtocolJson.decodeFromJsonElement<TableRef>(data))
    "tagSearch" -> OutTagSearch(ProtocolJson.decodeFromJsonElement<TagSearchRequest>(data))
    "userInactive" -> OutUserInactive(ProtocolJson.decodeFromJsonElement<UserInactiveRequest>(data))
    else -> throw IllegalArgumentException("Not a command of the client: $command")
}

/** The reply of the server to a request. Only some requests are answered with data; the rest with an empty reply. */
sealed interface Reply

/** A reply that does not read as what its request promises: the protocol has changed. */
class ReplyInvalid(val command: String, val data: JsonElement?, val error: String) : Reply

class ReplyChatPmHistory(val data: ChatPmHistory) : Reply

class ReplyGameHistory(val data: GamePage) : Reply

class ReplyGameInitLoad(val data: GameInit) : Reply

class ReplySeedGames(val data: GamePage) : Reply

/** Reads the data of the reply to a request called [command]; null if that request has no reply with data. */
fun decodeReply(command: String, data: JsonElement?): Reply? {
    return try {
        when (command) {
            "chatPmHistory" -> ReplyChatPmHistory(ProtocolJson.decodeFromJsonElement<ChatPmHistory>(data ?: kotlinx.serialization.json.JsonObject(emptyMap())))
            "gameHistory" -> ReplyGameHistory(ProtocolJson.decodeFromJsonElement<GamePage>(data ?: kotlinx.serialization.json.JsonObject(emptyMap())))
            "gameInitLoad" -> ReplyGameInitLoad(ProtocolJson.decodeFromJsonElement<GameInit>(data ?: kotlinx.serialization.json.JsonObject(emptyMap())))
            "seedGames" -> ReplySeedGames(ProtocolJson.decodeFromJsonElement<GamePage>(data ?: kotlinx.serialization.json.JsonObject(emptyMap())))
            else -> null
        }
    } catch (e: Exception) {
        ReplyInvalid(command, data, e.message ?: e.toString())
    }
}

